SELECT p.prod_id AS prodId, p.prod_name AS prodName, p.brand, p.client_id AS clientId, p.prod_price AS prodPrice, i.inventory_id AS inventoryId, i.ware_id AS wareId, i.quantity, i.last_inbound_date AS lastInboundDate, i.last_outbound_date AS lastOutboundDate, wa.ware_name AS wareName, wa.ware_address AS wareAddress FROM inventory i JOIN product p ON i.prod_id = p.prod_id JOIN category c ON p.prod_categoryid = c.prod_categoryid JOIN warehouse_area wa ON i.ware_id = wa.ware_id
AND i.client_id = #{clientId}
AND c.category_level1 = #{category1}
AND c.category_level2 = #{category2}
AND c.category_level3 = #{category3}
AND p.prod_name LIKE CONCAT('%', #{keyword}, '%')
AND p.brand LIKE CONCAT('%', #{keyword}, '%')
AND wa.ware_name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY i.quantity ASC
ORDER BY i.quantity DESC
ORDER BY p.prod_name ASC

SELECT DISTINCT c.category_level2
FROM inventory i
         JOIN product p  ON i.prod_id = p.prod_id
         JOIN category c ON p.prod_categoryid = c.prod_categoryid
WHERE c.category_level1 = #{category1}
  AND i.client_id        = #{clientId}

SELECT DISTINCT c.category_level3
FROM inventory i
         JOIN product p  ON i.prod_id = p.prod_id
         JOIN category c ON p.prod_categoryid = c.prod_categoryid
WHERE c.category_level2 = #{category2}
  AND i.client_id        = #{clientId}
